// Workflow B (Delaunay Productions) — Nœuds « Nettoyage : Actus brutes » et « Nettoyage : Articles »
// Calcule les lignes à supprimer dans un onglet. Une sortie par ligne, de la DERNIÈRE à la PREMIÈRE :
// en supprimant par le bas, les numéros des lignes restantes ne bougent pas.
//   - Actus brutes : doublons (même URL, ou même média + même titre) et actus de plus de N jours
//   - Articles     : articles de plus de N jours
// N = « Conservation dans le Sheet » (onglet Paramètres, 14 jours par défaut).
// Bloc commun recopié en tête des nœuds Code du workflow B (Delaunay Productions)
const params = Object.fromEntries(
  $('Lire Paramètres').all().map(i => [String(i.json['Paramètre'] || '').trim(), i.json['Valeur']])
);
const nombre = (cle, defaut) => { const v = parseFloat(String(params[cle] ?? '').replace(',', '.')); return isNaN(v) ? defaut : v; };
const NB_MIN_SOURCES = nombre('Nb minimum de sources différentes', 2);
const NB_MAX_SOURCES = nombre('Nb maximum de sources par article', 4);
const NB_MAX_ARTICLES = nombre("Nb max d'articles par passage", 3);
const ATTENTE_H = nombre('Attente si une seule source', 48);
const CONSERVATION_J = nombre('Conservation dans le Sheet', 14);
const PROMPT = String(params['Prompt de rédaction (IA)'] || '').trim();
const FIAB_MIN = nombre('Fiabilité minimum (source unique)', 3);
const FIAB_GRAND_MEDIA = nombre('Fiabilité « grand média » (source unique, tous thèmes)', 4);
const PLAFOND_MEDIAS = nombre('Plafond médias dans le score', 3);
const BONUS_DIVERSITE = nombre('Bonus diversité', 4);
const BONUS_NORMANDIE = nombre('Bonus Normandie', 3);
const fiab = l => { const f = Number(l['Fiabilité source']); return isNaN(f) || l['Fiabilité source'] === '' ? 3 : f; };
const reconnue = l => fiab(l) >= FIAB_MIN;            // les sites inconnus (fiabilité 2) ne comptent pas
const prioriteDe = l => Number(l['Priorité thème']) || 1;
// Source unique acceptée : thème de priorité 1-2, OU grand média (fiabilité ≥ seuil), quel que soit le thème
const sourceUniqueOK = (prio, fiabilite) => prio < 3 || (Number(fiabilite) || 0) >= FIAB_GRAND_MEDIA;

const sansAccentB = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
// « Ouest-France », « Ouest France » et « ouest-france.fr » = le même média
const cleMedia = m => sansAccentB(m).replace(/\.(fr|com|net|org)$/, '').replace(/^www\./, '').replace(/[^a-z0-9]/g, '');
const cleTitre = t => sansAccentB(t).replace(/[^a-z0-9]+/g, ' ').trim();
const cleUrlB = u => {
  const m = String(u || '').trim().match(/^https?:\/\/([^\/?#]+)([^?#]*)/i);
  return m ? m[1].replace(/^www\./i, '').toLowerCase() + m[2].replace(/\/+$/, '') : String(u || '').trim();
};
// Deux lignes sont le même article si elles ont la même clé d'URL, ou le même média + le même titre
const signatures = r => [String(r['Clé (URL normalisée)'] || ''), cleMedia(r['Média source']) + '|' + cleTitre(r['Titre'])];
const RANG_STATUT = { 'Utilisé': 4, 'Doublon': 3, 'Ignoré': 2, 'Nouveau': 1 };

// Actus lues dans le Sheet, sans doublons (la suppression physique est faite par « Nettoyage : Actus brutes »)
const actus = (() => {
  const brutes = $('Lire Actus').all().map(i => i.json).filter(r => r && r['Clé (URL normalisée)']);
  const vues = new Map();
  const gardees = [];
  for (const r of [...brutes].sort((a, b) => (RANG_STATUT[b['Statut']] || 0) - (RANG_STATUT[a['Statut']] || 0))) {
    if (signatures(r).some(s => vues.has(s))) continue;
    signatures(r).forEach(s => vues.set(s, true));
    gardees.push(r);
  }
  return gardees;
})();
// Une actu « Nouveau » plus vieille que le délai d'attente n'est plus proposée (elle passe en « Ignoré »)
const fraiche = r => { const t = new Date(r['Date publication']).getTime(); return isNaN(t) || Date.now() - t < ATTENTE_H * 3600 * 1000; };

const ONGLET = 'Actus brutes';
const limite = Date.now() - CONSERVATION_J * 24 * 3600 * 1000;
const vieux = d => { const t = new Date(d).getTime(); return !isNaN(t) && t < limite; };

const lignes = $(ONGLET === 'Articles' ? 'Lire Articles' : 'Lire Actus').all().map(i => i.json)
  .filter(r => r && Number(r.row_number) > 1);
const aSupprimer = new Map(); // row_number -> raison

if (ONGLET === 'Articles') {
  for (const r of lignes) {
    if (!r['ID article'] && !r['Titre']) continue;
    if (vieux(r['Date création'])) aSupprimer.set(r.row_number, 'plus de ' + CONSERVATION_J + ' jours');
  }
} else {
  // On garde la ligne au statut le plus avancé (Utilisé > Doublon > Ignoré > Nouveau), puis la plus ancienne
  const tries = [...lignes].sort((a, b) =>
    ((RANG_STATUT[b['Statut']] || 0) - (RANG_STATUT[a['Statut']] || 0)) || (a.row_number - b.row_number));
  const vues = new Set();
  for (const r of tries) {
    if (!r['Clé (URL normalisée)'] && !r['Titre']) continue;
    const sig = signatures(r).filter(s => s && s !== '|');
    if (sig.some(s => vues.has(s))) { aSupprimer.set(r.row_number, 'doublon'); continue; }
    sig.forEach(s => vues.add(s));
    if (vieux(r['Date publication'] || r['Date collecte'])) aSupprimer.set(r.row_number, 'plus de ' + CONSERVATION_J + ' jours');
  }
}

return [...aSupprimer.entries()]
  .sort((a, b) => b[0] - a[0])
  .map(([ligne, raison]) => ({ json: { ligne, raison } }));

