// Workflow B (Delaunay Productions) — Nœud « Préparer l'article »
// Entrée : la réponse de l'IA « Rédiger l'article ». Sortie : une ligne pour l'onglet « Articles ».
const photos = $('Lire Photos').all().map(i => i.json)
  .filter(p => p && p['URL image'] && String(p['Autorisation obtenue']).trim() === 'Oui');

// Extrait le JSON de la réponse d'un modèle IA, même s'il a écrit son raisonnement avant
// (« Thinking Process… », balises <think>…</think>, bloc ```json…```).
// On cherche en partant de la FIN le dernier objet JSON valide qui contient la clé attendue :
// la réponse finale vient toujours après le raisonnement.
const texteIA = r => {
  if (!r) return '';
  const v = r.text ?? r.output ?? r.response ?? r.content ?? '';
  return typeof v === 'string' ? v : JSON.stringify(v);
};
function lireJsonIA(brut, cleAttendue) {
  let s = String(brut || '').replace(/<think>[\s\S]*?<\/think>/gi, ' ').replace(/```(?:json)?/gi, ' ');
  const valide = o => o && typeof o === 'object' && (!cleAttendue || (o[cleAttendue] !== undefined
    && !/^\s*(\.\.\.|…)?\s*$/.test(typeof o[cleAttendue] === 'string' ? o[cleAttendue] : 'x')));
  for (let debut = s.lastIndexOf('{'); debut >= 0; debut = s.lastIndexOf('{', debut - 1)) {
    // fermeture équilibrée (en ignorant les accolades dans les chaînes)
    let prof = 0, dansChaine = false, echap = false, fin = -1;
    for (let i = debut; i < s.length; i++) {
      const c = s[i];
      if (dansChaine) { if (echap) echap = false; else if (c === '\\') echap = true; else if (c === '"') dansChaine = false; continue; }
      if (c === '"') dansChaine = true;
      else if (c === '{') prof++;
      else if (c === '}') { prof--; if (prof === 0) { fin = i; break; } }
    }
    if (fin < 0) continue;
    try { const o = JSON.parse(s.slice(debut, fin + 1)); if (valide(o)) return o; } catch (e) { /* on essaie plus haut */ }
  }
  return null;
}

// Longueur minimale du corps (sans le bloc Sources) : réglage « Nb de mots minimum par article » de l'onglet Paramètres
let reglages = {};
try { reglages = Object.fromEntries($('Lire Paramètres').all().map(i => [String(i.json['Paramètre'] || '').trim(), i.json['Valeur']])); } catch (e) { /* réglage par défaut */ }
const MIN_MOTS = parseInt(reglages['Nb de mots minimum par article'], 10) || 120;
const compterMots = t => (String(t || '').match(/[\p{L}\p{N}][\p{L}\p{N}'’-]*/gu) || []).length;
const maintenant = new Date();
const horodatage = maintenant.toISOString().slice(0, 16).replace(/[-:T]/g, '');
const norm = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').trim().toLowerCase();

// Photo : d'abord une photo du thème, sinon une photo du pôle. On alterne entre les photos disponibles.
const choisirPhoto = (ev, rang) => {
  const duTheme = photos.filter(p => norm(p['Thème (optionnel)']) && norm(p['Thème (optionnel)']) === norm(ev.theme));
  const poles = String(ev.pole || '').split(/\s*;\s*/).map(norm).filter(Boolean);
  const duPole = photos.filter(p => !norm(p['Thème (optionnel)']) && poles.includes(norm(p['Pôle'])));
  const liste = duTheme.length ? duTheme : duPole;
  return liste.length ? liste[(rang + Math.floor(Date.now() / 86400000)) % liste.length] : null;
};
const nettoyerMeta = s => String(s || '').replace(/\s+/g, ' ').trim().slice(0, 160);

const sortie = [];
const echecs = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  let ev;
  try { ev = $('Extraire le texte & regrouper').itemMatching(i).json; }
  catch (e) { ev = ($('Extraire le texte & regrouper').all()[i] || {}).json; }
  if (!ev || !ev.sources) continue;
  const brut = texteIA(items[i].json);
  const a = lireJsonIA(brut, 'titre');
  if (!a || !a.corps) { // réponse IA inutilisable : on n'écrit rien, mais on le dit
    echecs.push(`• ${ev.theme} – ${ev.sujet} : ${brut ? 'pas de JSON {titre, chapo, corps} dans la réponse. Fin de la réponse : « …' + brut.slice(-200).replace(/\s+/g, ' ') + ' »' : 'réponse vide (modèle hors ligne ou erreur IA)'}`);
    continue;
  }

  // Les sources citées viennent de NOS données (pas de l'IA) pour éviter toute URL inventée
  const sources = ev.sources.map(s => `${s.media} : ${s.url}`);
  const corps = String(a.corps).trim() + '\n\nSources :\n' + sources.map(s => '- ' + s).join('\n');
  const photo = choisirPhoto(ev, i);
  const nbMots = compterMots(a.corps);
  const motsCles = Array.isArray(a.motsCles) ? a.motsCles.join(', ') : String(a.motsCles || '');

  sortie.push({
    json: {
      'ID article': `ART-DP-${horodatage}-${i + 1}`,
      'Date création': maintenant.toISOString(),
      'ID événement': ev.idEvenement,
      'Titre': String(a.titre || '').trim(),
      'Chapô': String(a.chapo || '').trim(),
      "Corps de l'article": corps,
      'Thème': ev.theme,
      'Pôle': ev.pole || '',
      'Normandie': ev.normandie ? 'Oui' : 'Non',
      'Meta description (SEO)': nettoyerMeta(a.metaDescription),
      'Mots-clés SEO': motsCles.replace(/\s+/g, ' ').trim(),
      'Sources citées (média + URL)': sources.join('\n'),
      'Nb de sources': ev.sources.length,
      'Photo (URL)': photo ? photo['URL image'] : '',
      'Crédit photo': photo ? photo['Crédit'] : '',
      'Licence photo': photo ? photo['Licence'] : 'Visuel générique',
      'Statut': 'À relire',
      'Date publication': '',
      'URL publication': '',
      'Relu par': '',
      'Format': ev.format || '',
      // champs internes (non écrits dans le Sheet) : tri des articles trop courts
      _nbMots: nbMots,
      _garder: nbMots >= MIN_MOTS,
    },
  });
}
if (echecs.length && !sortie.length) {
  throw new Error(`Aucun article exploitable (${echecs.length} réponse(s) IA sans JSON).\n${echecs.join('\n')}\n\n` +
    `Cause probable : le modèle écrit son raisonnement et n'a pas fini, ou n'a pas terminé par le JSON. ` +
    `Dans le sous-nœud Ollama : n'active PAS « Format : JSON » ; augmente Context Length (16384) et vérifie qu'Ollama tourne.`);
}
if (echecs.length) console.log('Réponses IA ignorées :\n' + echecs.join('\n'));
const courts = sortie.filter(o => !o.json._garder);
if (courts.length) console.log(`Articles de moins de ${MIN_MOTS} mots écartés : ` + courts.map(o => `${o.json['Thème']} – ${o.json['Titre']} (${o.json._nbMots} mots)`).join(' | '));
return sortie;

// Workflow B (Delaunay Productions) — Nœud « Scorer & sélectionner »
// Entrée : la réponse de l'IA « Regrouper en sujets » (un item par thème).
// Sortie : les sujets à rédiger (2 médias reconnus, ou 1 seul si thème de priorité 1-2 ou grand média) + les doublons.
// Bloc commun recopié en tête des nœuds Code du workflow B (Delaunay Productions)
