// Source unique acceptée : thème de priorité 1-2, OU grand média (fiabilité ≥ seuil), quel que soit le thème
const sourceUniqueOK = (prio, fiabilite) => prio < 3 || (Number(fiabilite) || 0) >= FIAB_GRAND_MEDIA;

const sansAccentB = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
// « Ouest-France », « Ouest France » et « ouest-france.fr » = le même média
const cleMedia = m => sansAccentB(m).replace(/\.(fr|com|net|org)$/, '').replace(/^www\./, '').replace(/[^a-z0-9]/g, '');
const cleTitre = t => sansAccentB(t).replace(/[^a-z0-9]+/g, ' ').trim();
const cleUrlB = u => {
  const m = String(u || '').trim().match(/^https?:\/\/([^\/?#]+)([^?#]*)/i);
  return m ? m[1].replace(/^www\./i, '').toLowerCase() + m[2].replace(/\/+$/, '') : String(u || '').trim();
};
// Deux lignes sont le même article si elles ont la même clé d'URL, ou le même média + le même titre
const signatures = r => [String(r['Clé (URL normalisée)'] || ''), cleMedia(r['Média source']) + '|' + cleTitre(r['Titre'])];
const RANG_STATUT = { 'Utilisé': 4, 'Doublon': 3, 'Ignoré': 2, 'Nouveau': 1 };

// Actus lues dans le Sheet, sans doublons (la suppression physique est faite par « Nettoyage : Actus brutes »)
const actus = (() => {
  const brutes = $('Lire Actus').all().map(i => i.json).filter(r => r && r['Clé (URL normalisée)']);
  const vues = new Map();
  const gardees = [];
  for (const r of [...brutes].sort((a, b) => (RANG_STATUT[b['Statut']] || 0) - (RANG_STATUT[a['Statut']] || 0))) {
    if (signatures(r).some(s => vues.has(s))) continue;
    signatures(r).forEach(s => vues.set(s, true));
    gardees.push(r);
  }
  return gardees;
})();
// Une actu « Nouveau » plus vieille que le délai d'attente n'est plus proposée (elle passe en « Ignoré »)
const fraiche = r => { const t = new Date(r['Date publication']).getTime(); return isNaN(t) || Date.now() - t < ATTENTE_H * 3600 * 1000; };

const parCle = Object.fromEntries(actus.map(r => [r['Clé (URL normalisée)'], r]));
const maintenant = Date.now();

// Angle éditorial et pôle de chaque thème (onglet Thèmes)
const infosTheme = {};
try {
  for (const t of $('Lire Thèmes').all().map(i => i.json)) {
    if (t['Thème']) infosTheme[String(t['Thème']).trim()] = { pole: String(t['Pôle'] || '').trim(), angle: String(t["Angle éditorial (pour l'IA)"] || '').trim() };
  }
} catch (e) { /* onglet absent */ }

// Extrait le JSON de la réponse d'un modèle IA, même s'il a écrit son raisonnement avant
// (« Thinking Process… », balises <think>…</think>, bloc ```json…```).
// On cherche en partant de la FIN le dernier objet JSON valide qui contient la clé attendue :
// la réponse finale vient toujours après le raisonnement.
const texteIA = r => {
  if (!r) return '';
  const v = r.text ?? r.output ?? r.response ?? r.content ?? '';
  return typeof v === 'string' ? v : JSON.stringify(v);
};
function lireJsonIA(brut, cleAttendue) {
  let s = String(brut || '').replace(/<think>[\s\S]*?<\/think>/gi, ' ').replace(/```(?:json)?/gi, ' ');
  const valide = o => o && typeof o === 'object' && (!cleAttendue || (o[cleAttendue] !== undefined
    && !/^\s*(\.\.\.|…)?\s*$/.test(typeof o[cleAttendue] === 'string' ? o[cleAttendue] : 'x')));
  for (let debut = s.lastIndexOf('{'); debut >= 0; debut = s.lastIndexOf('{', debut - 1)) {
    // fermeture équilibrée (en ignorant les accolades dans les chaînes)
    let prof = 0, dansChaine = false, echap = false, fin = -1;
    for (let i = debut; i < s.length; i++) {
      const c = s[i];
      if (dansChaine) { if (echap) echap = false; else if (c === '\\') echap = true; else if (c === '"') dansChaine = false; continue; }
      if (c === '"') dansChaine = true;
      else if (c === '{') prof++;
      else if (c === '}') { prof--; if (prof === 0) { fin = i; break; } }
    }
    if (fin < 0) continue;
    try { const o = JSON.parse(s.slice(debut, fin + 1)); if (valide(o)) return o; } catch (e) { /* on essaie plus haut */ }
  }
  return null;
}

const slug = s => String(s).normalize('NFD').replace(/[̀-ͯ]/g, '')
  .toUpperCase().replace(/[^A-Z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 20);
// Date + heure dans l'identifiant : deux lancements le même jour ne produisent pas le même ID
const jour = new Date().toISOString().slice(0, 16).replace(/[-:]/g, '').replace('T', '-');

// ---------- Articles déjà rédigés (onglet Articles) ----------
// Un sujet n'est PAS re-rédigé (et ne coûte pas d'appel IA) si :
//   1. une de ses actus a déjà servi à un article (même URL), ou
//   2. un article du même thème, écrit dans les 72 h, traite visiblement du même sujet.
const MOTS_VIDES = new Set(('le la les un une des du de d l au aux et ou en dans sur pour par avec sans ce cet cette ces son sa ses leur leurs ' +
  'qui que quoi dont est sont a ont ete etre fait plus moins tres aussi apres avant contre face entre lors depuis ' +
  'drone drones video videos camera cameras evenement evenements evenementiel nouveau nouvelle nouveaux nouvelles ' +
  'il elle ils elles on se ne pas nous vous lui y ca').split(' '));
const motsDe = (t, theme) => {
  const exclus = new Set(cleTitre(theme).split(' '));
  return new Set(cleTitre(t).split(' ').filter(m => m.length > 2 && !MOTS_VIDES.has(m) && !exclus.has(m)));
};
const recouvrement = (a, b) => {
  if (!a.size || !b.size) return { taux: 0, communs: 0 };
  let n = 0; a.forEach(m => { if (b.has(m)) n++; });
  return { taux: n / Math.min(a.size, b.size), communs: n };
};
const articles = $('Lire Articles').all().map(i => i.json).filter(r => r && r['ID article']);
const clesDejaUtilisees = new Map(); // clé d'URL -> ID article
for (const a of articles) {
  for (const u of String(a['Sources citées (média + URL)'] || '').match(/https?:\/\/\S+/g) || []) clesDejaUtilisees.set(cleUrlB(u), a['ID article']);
}
for (const r of $('Lire Actus').all().map(i => i.json)) {
  if (r && r['Article lié (ID)'] && /^ART-/.test(r['Article lié (ID)']) && r['Clé (URL normalisée)']) clesDejaUtilisees.set(r['Clé (URL normalisée)'], r['Article lié (ID)']);
}
const recents = articles.filter(a => Date.now() - new Date(a['Date création']).getTime() < 72 * 3600 * 1000);
function dejaRedige(ev, lignes) {
  for (const l of lignes) {
    const k = l['Clé (URL normalisée)'];
    if (clesDejaUtilisees.has(k)) return { id: clesDejaUtilisees.get(k), raison: 'source déjà utilisée' };
  }
  const motsEv = motsDe([ev.sujet, ...lignes.map(l => l['Titre'])].join(' '), ev.theme);
  for (const a of recents) {
    if (cleTitre(a['Thème']) !== cleTitre(ev.theme)) continue;
    const r = recouvrement(motsEv, motsDe(a['Titre'] + ' ' + a['Chapô'], ev.theme));
    if (r.communs >= 3 && r.taux >= 0.5) return { id: a['ID article'], raison: `même sujet (${Math.round(r.taux * 100)} % de mots communs)` };
  }
  return null;
}

// Thèmes qui n'ont pas eu d'article depuis 72 h : bonus de diversité
const themesRecents = new Set(recents.map(a => cleTitre(a['Thème'])));

// ---------- Garde-fou contre les erreurs de regroupement de l'IA ----------
// Deux actus ne restent ensemble que si leurs titres / chapôs partagent au moins un mot qui compte
// (marque, modèle, lieu, nom propre, texte réglementaire…). Sinon le groupe est coupé en plusieurs sujets.
const MOTS_NEUTRES = new Set(('avec avant apres sans pour dans depuis contre entre sous chez vers leur leurs cette ces sont etait '
  + 'plus moins tres tout tous toute toutes encore deja aussi mais donc alors comme quand elle elles ils nous vous fait faire '
  + 'drone drones video videos camera cameras photo photos image images tournage tournages evenement evenements evenementiel '
  + 'salon salons festival festivals spectacle production productions direct live nouveau nouvelle nouveaux nouvelles annonce '
  + 'officiel officielle france francais francaise normandie premier premiere dernier derniere grand grande petit petite '
  + 'semaine weekend week-end lundi mardi mercredi jeudi vendredi samedi dimanche janvier fevrier mars avril juin juillet '
  + 'aout septembre octobre novembre decembre annee prix test quoi comment pourquoi face point info infos actu actus').split(' '));
const sansAcc = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
function motsCles(a, theme) {
  const motsTheme = new Set(sansAcc(theme).split(/[^a-z0-9]+/));
  const texte = sansAcc(`${a.titre || ''} ${String(a.extrait || '').slice(0, 160)}`);
  const mots = new Set();
  for (const m of texte.split(/[^a-z0-9-]+/)) {
    for (const p of m.split('-')) if (p.length >= 4 && !MOTS_NEUTRES.has(p) && !motsTheme.has(p) && !/^\d+$/.test(p)) mots.add(p);
  }
  return mots;
}
function verifierPaquets(paquets, groupe) {
  const parId = Object.fromEntries((groupe.liste || []).map(a => [a.id, a]));
  const sortie = [];
  for (const p of paquets) {
    const ids = (p.ids || []).filter(id => parId[id]);
    if (ids.length < 2) { sortie.push(p); continue; }
    const mots = Object.fromEntries(ids.map(id => [id, motsCles(parId[id], groupe.theme)]));
    const lies = (x, y) => [...mots[x]].some(m => mots[y].has(m));
    const restants = new Set(ids);
    const comps = [];
    while (restants.size) {
      const depart = restants.values().next().value;
      const comp = [depart]; restants.delete(depart);
      for (let k = 0; k < comp.length; k++) for (const y of [...restants]) if (lies(comp[k], y)) { comp.push(y); restants.delete(y); }
      comps.push(comp);
    }
    if (comps.length === 1) sortie.push(p);
    else for (const comp of comps) sortie.push({ sujet: parId[comp[0]].titre, ids: comp, coupeParControle: true });
  }
  return sortie;
}

// ---------- Groupes à traiter ----------
// 1. Réponses de l'IA (thèmes avec plusieurs actus)
const groupes = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  let groupe;
  try { groupe = $('Préparer regroupement').itemMatching(i).json; }
  catch (e) { groupe = ($('Préparer regroupement').all()[i] || {}).json; } // le nœud IA sort 1 item par entrée, dans l'ordre
  if (!groupe || !groupe.liste || groupe.vide) continue;
  const rep = lireJsonIA(texteIA(items[i].json), 'evenements');
  // Si l'IA a échoué : chaque actu devient son propre sujet
  const paquets = rep && Array.isArray(rep.evenements) ? rep.evenements : groupe.liste.map(a => ({ sujet: a.titre, ids: [a.id] }));
  groupes.push({ ...groupe, paquets: verifierPaquets(paquets, groupe), rang: i + 1 });
}
// 2. Thèmes avec une seule actu reconnue (pas besoin de l'IA pour regrouper)
const dejaGroupes = new Set(groupes.map(g => g.theme));
const nouvellesReconnues = actus.filter(r => String(r['Statut']).trim() === 'Nouveau' && r['Thème détecté'] && reconnue(r) && fraiche(r));
const parTheme = {};
for (const r of nouvellesReconnues) (parTheme[r['Thème détecté']] = parTheme[r['Thème détecté']] || []).push(r);
let rangSeul = 100;
for (const [theme, lignes] of Object.entries(parTheme)) {
  if (dejaGroupes.has(theme) || lignes.length !== 1) continue;
  groupes.push({
    theme, pole: lignes[0]['Pôle'] || '', rang: ++rangSeul,
    cles: { a1: lignes[0]['Clé (URL normalisée)'] },
    paquets: [{ sujet: lignes[0]['Titre'], ids: ['a1'] }],
  });
}

// ---------- Construction et score des sujets ----------
const evenements = [];
for (const groupe of groupes) {
  const dejaPris = new Set();
  groupe.paquets.forEach((p, n) => {
    const lignes = (p.ids || [])
      .filter(id => groupe.cles[id] && !dejaPris.has(id))
      .map(id => { dejaPris.add(id); return parCle[groupe.cles[id]]; })
      .filter(Boolean);
    if (!lignes.length) return;
    // un seul article par média (le plus récent), sources inconnues exclues
    const parMedia = {};
    for (const l of lignes.filter(reconnue)) {
      const m = cleMedia(l['Média source']);
      if (!parMedia[m] || new Date(l['Date publication']) > new Date(parMedia[m]['Date publication'])) parMedia[m] = l;
    }
    const sources = Object.values(parMedia).sort((a, b) => fiab(b) - fiab(a)).slice(0, NB_MAX_SOURCES);
    if (!sources.length) return;
    const priorite = prioriteDe(sources[0]);
    // Règle de croisement : 2 médias reconnus, sauf thème de priorité 1-2 ou grand média (source unique acceptée)
    if (sources.length < NB_MIN_SOURCES && !sourceUniqueOK(priorite, fiab(sources[0]))) return;

    const normandie = lignes.some(l => String(l['Normandie']).trim() === 'Oui');
    const fiabMoy = sources.reduce((s, l) => s + fiab(l), 0) / sources.length;
    const plusRecente = Math.max(...sources.map(l => new Date(l['Date publication']).getTime() || 0));
    const bonusFraicheur = maintenant - plusRecente < 12 * 3600 * 1000 ? 2 : 0;
    const bonusDiversite = themesRecents.has(cleTitre(groupe.theme)) ? 0 : BONUS_DIVERSITE;
    const bonusNormandie = normandie ? BONUS_NORMANDIE : 0;
    const score = Math.round((3 * Math.min(sources.length, PLAFOND_MEDIAS) + fiabMoy + 2 * priorite + bonusFraicheur + bonusDiversite + bonusNormandie) * 10) / 10;
    const info = infosTheme[groupe.theme] || {};

    const ev = {
      idEvenement: `EVT-${jour}-${slug(groupe.theme)}-${groupe.rang}${String.fromCharCode(65 + n)}`,
      theme: groupe.theme,
      pole: groupe.pole || info.pole || '',
      angle: info.angle || '',
      normandie,
      sujet: p.sujet || sources[0]['Titre'],
      score,
      sourceUnique: sources.length === 1,
      cles: lignes.map(l => l['Clé (URL normalisée)']),
      sources: sources.map(l => ({
        media: l['Média source'],
        url: l['URL'],
        titre: l['Titre'],
        extrait: l['Résumé / extrait'] || '',
      })),
    };
    const doublon = dejaRedige(ev, lignes);
    ev.aRediger = !doublon;
    if (doublon) { ev.doublonDe = doublon.id; ev.raisonDoublon = doublon.raison; }
    evenements.push(ev);
  });
}

// ---------- Sélection ----------
// On rédige jusqu'à NB_MAX_ARTICLES par passage ; les autres attendent le passage suivant.
// Pour varier les sujets, chaque sujet supplémentaire d'un même thème dans le passage perd 8 points.
const candidats = evenements.filter(e => e.aRediger);
const choisis = [];
const parThemeChoisi = {};
while (choisis.length < NB_MAX_ARTICLES && candidats.length) {
  candidats.sort((a, b) => (b.score - 8 * (parThemeChoisi[b.theme] || 0)) - (a.score - 8 * (parThemeChoisi[a.theme] || 0)));
  const e = candidats.shift();
  parThemeChoisi[e.theme] = (parThemeChoisi[e.theme] || 0) + 1;
  choisis.push(e);
}
const doublons = evenements.filter(e => !e.aRediger);
return [...choisis, ...doublons].map(e => ({ json: e }));

// Workflow B (Delaunay Productions) — Nœud « Préparer regroupement »
// Une sortie par thème qui a AU MOINS 2 actus « Nouveau » de sources reconnues : l'IA les regroupe en sujets.
// Les thèmes qui n'ont qu'une seule actu n'ont pas besoin de l'IA : « Scorer & sélectionner » les traite directement.
// Bloc commun recopié en tête des nœuds Code du workflow B (Delaunay Productions)
const params = Object.fromEntries(
  $('Lire Paramètres').all().map(i => [String(i.json['Paramètre'] || '').trim(), i.json['Valeur']])
);
const nombre = (cle, defaut) => { const v = parseFloat(String(params[cle] ?? '').replace(',', '.')); return isNaN(v) ? defaut : v; };
const NB_MIN_SOURCES = nombre('Nb minimum de sources différentes', 2);
const NB_MAX_SOURCES = nombre('Nb maximum de sources par article', 4);
const NB_MAX_ARTICLES = nombre("Nb max d'articles par passage", 3);
const ATTENTE_H = nombre('Attente si une seule source', 48);
const CONSERVATION_J = nombre('Conservation dans le Sheet', 14);
const PROMPT = String(params['Prompt de rédaction (IA)'] || '').trim();
const FIAB_MIN = nombre('Fiabilité minimum (source unique)', 3);
const FIAB_GRAND_MEDIA = nombre('Fiabilité « grand média » (source unique, tous thèmes)', 4);
const PLAFOND_MEDIAS = nombre('Plafond médias dans le score', 3);
const BONUS_DIVERSITE = nombre('Bonus diversité', 4);
const BONUS_NORMANDIE = nombre('Bonus Normandie', 3);
const fiab = l => { const f = Number(l['Fiabilité source']); return isNaN(f) || l['Fiabilité source'] === '' ? 3 : f; };
const reconnue = l => fiab(l) >= FIAB_MIN;            // les sites inconnus (fiabilité 2) ne comptent pas
const prioriteDe = l => Number(l['Priorité thème']) || 1;
// Source unique acceptée : thème de priorité 1-2, OU grand média (fiabilité ≥ seuil), quel que soit le thème
const sourceUniqueOK = (prio, fiabilite) => prio < 3 || (Number(fiabilite) || 0) >= FIAB_GRAND_MEDIA;

const sansAccentB = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
// « Ouest-France », « Ouest France » et « ouest-france.fr » = le même média
const cleMedia = m => sansAccentB(m).replace(/\.(fr|com|net|org)$/, '').replace(/^www\./, '').replace(/[^a-z0-9]/g, '');
const cleTitre = t => sansAccentB(t).replace(/[^a-z0-9]+/g, ' ').trim();
const cleUrlB = u => {
  const m = String(u || '').trim().match(/^https?:\/\/([^\/?#]+)([^?#]*)/i);
  return m ? m[1].replace(/^www\./i, '').toLowerCase() + m[2].replace(/\/+$/, '') : String(u || '').trim();
};
// Deux lignes sont le même article si elles ont la même clé d'URL, ou le même média + le même titre
const signatures = r => [String(r['Clé (URL normalisée)'] || ''), cleMedia(r['Média source']) + '|' + cleTitre(r['Titre'])];
const RANG_STATUT = { 'Utilisé': 4, 'Doublon': 3, 'Ignoré': 2, 'Nouveau': 1 };

// Actus lues dans le Sheet, sans doublons (la suppression physique est faite par « Nettoyage : Actus brutes »)
const actus = (() => {
  const brutes = $('Lire Actus').all().map(i => i.json).filter(r => r && r['Clé (URL normalisée)']);
  const vues = new Map();
  const gardees = [];
  for (const r of [...brutes].sort((a, b) => (RANG_STATUT[b['Statut']] || 0) - (RANG_STATUT[a['Statut']] || 0))) {
    if (signatures(r).some(s => vues.has(s))) continue;
    signatures(r).forEach(s => vues.set(s, true));
    gardees.push(r);
  }
  return gardees;
})();
// Une actu « Nouveau » plus vieille que le délai d'attente n'est plus proposée (elle passe en « Ignoré »)
const fraiche = r => { const t = new Date(r['Date publication']).getTime(); return isNaN(t) || Date.now() - t < ATTENTE_H * 3600 * 1000; };

const nouvelles = actus.filter(r => String(r['Statut']).trim() === 'Nouveau' && r['Thème détecté'] && reconnue(r) && fraiche(r));

const parTheme = {};
for (const r of nouvelles) (parTheme[r['Thème détecté']] = parTheme[r['Thème détecté']] || []).push(r);

const sortie = [];
for (const [theme, lignes] of Object.entries(parTheme)) {
  const medias = new Set(lignes.map(l => cleMedia(l['Média source'])));
  const eligible = medias.size >= NB_MIN_SOURCES || lignes.some(l => sourceUniqueOK(prioriteDe(l), fiab(l)));
  if (!eligible || lignes.length < 2) continue;
  // 40 actus maximum par appel : au-delà, le modèle local se perd. Les plus récentes d'abord.
  const retenues = [...lignes].sort((a, b) => new Date(b['Date publication']) - new Date(a['Date publication'])).slice(0, 40);
  const liste = retenues.map((l, k) => ({
    id: 'a' + (k + 1),
    titre: l['Titre'],
    media: l['Média source'],
    date: l['Date publication'],
    extrait: String(l['Résumé / extrait'] || '').slice(0, 200),
  }));
  sortie.push({
    json: {
      theme,
      pole: retenues[0]['Pôle'] || '',
      liste,
      cles: Object.fromEntries(retenues.map((l, k) => ['a' + (k + 1), l['Clé (URL normalisée)']])),
    },
  });
}
// Aucun thème à regrouper : un élément « vide » pour que la suite du workflow s'exécute quand même
// (les thèmes à actu unique sont traités dans « Scorer & sélectionner »). L'IA le traite en une seconde.
if (!sortie.length) sortie.push({ json: { vide: true, theme: '—', pole: '', liste: [{ id: 'a1', titre: '(aucune actu à regrouper)' }], cles: {} } });
return sortie;

// Workflow B (Delaunay Productions) — Nœud « Actus expirées »
// Les actus restées « Nouveau » au-delà du délai d'attente (pas de 2e source) passent en « Ignoré ».
// Bloc commun recopié en tête des nœuds Code du workflow B (Delaunay Productions)
const params = Object.fromEntries(
  $('Lire Paramètres').all().map(i => [String(i.json['Paramètre'] || '').trim(), i.json['Valeur']])
);
const nombre = (cle, defaut) => { const v = parseFloat(String(params[cle] ?? '').replace(',', '.')); return isNaN(v) ? defaut : v; };
const NB_MIN_SOURCES = nombre('Nb minimum de sources différentes', 2);
const NB_MAX_SOURCES = nombre('Nb maximum de sources par article', 4);
const NB_MAX_ARTICLES = nombre("Nb max d'articles par passage", 3);
const ATTENTE_H = nombre('Attente si une seule source', 48);
const CONSERVATION_J = nombre('Conservation dans le Sheet', 14);
const PROMPT = String(params['Prompt de rédaction (IA)'] || '').trim();
const FIAB_MIN = nombre('Fiabilité minimum (source unique)', 3);
const FIAB_GRAND_MEDIA = nombre('Fiabilité « grand média » (source unique, tous thèmes)', 4);
const PLAFOND_MEDIAS = nombre('Plafond médias dans le score', 3);
const BONUS_DIVERSITE = nombre('Bonus diversité', 4);
const BONUS_NORMANDIE = nombre('Bonus Normandie', 3);
const fiab = l => { const f = Number(l['Fiabilité source']); return isNaN(f) || l['Fiabilité source'] === '' ? 3 : f; };
const reconnue = l => fiab(l) >= FIAB_MIN;            // les sites inconnus (fiabilité 2) ne comptent pas
const prioriteDe = l => Number(l['Priorité thème']) || 1;
// Source unique acceptée : thème de priorité 1-2, OU grand média (fiabilité ≥ seuil), quel que soit le thème
const sourceUniqueOK = (prio, fiabilite) => prio < 3 || (Number(fiabilite) || 0) >= FIAB_GRAND_MEDIA;

const sansAccentB = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
// « Ouest-France », « Ouest France » et « ouest-france.fr » = le même média
const cleMedia = m => sansAccentB(m).replace(/\.(fr|com|net|org)$/, '').replace(/^www\./, '').replace(/[^a-z0-9]/g, '');
const cleTitre = t => sansAccentB(t).replace(/[^a-z0-9]+/g, ' ').trim();
const cleUrlB = u => {
  const m = String(u || '').trim().match(/^https?:\/\/([^\/?#]+)([^?#]*)/i);
  return m ? m[1].replace(/^www\./i, '').toLowerCase() + m[2].replace(/\/+$/, '') : String(u || '').trim();
};
// Deux lignes sont le même article si elles ont la même clé d'URL, ou le même média + le même titre
const signatures = r => [String(r['Clé (URL normalisée)'] || ''), cleMedia(r['Média source']) + '|' + cleTitre(r['Titre'])];
const RANG_STATUT = { 'Utilisé': 4, 'Doublon': 3, 'Ignoré': 2, 'Nouveau': 1 };

// Actus lues dans le Sheet, sans doublons (la suppression physique est faite par « Nettoyage : Actus brutes »)
const actus = (() => {
  const brutes = $('Lire Actus').all().map(i => i.json).filter(r => r && r['Clé (URL normalisée)']);
  const vues = new Map();
  const gardees = [];
  for (const r of [...brutes].sort((a, b) => (RANG_STATUT[b['Statut']] || 0) - (RANG_STATUT[a['Statut']] || 0))) {
    if (signatures(r).some(s => vues.has(s))) continue;
    signatures(r).forEach(s => vues.set(s, true));
    gardees.push(r);
  }
  return gardees;
})();
// Une actu « Nouveau » plus vieille que le délai d'attente n'est plus proposée (elle passe en « Ignoré »)
const fraiche = r => { const t = new Date(r['Date publication']).getTime(); return isNaN(t) || Date.now() - t < ATTENTE_H * 3600 * 1000; };

const limite = Date.now() - ATTENTE_H * 3600 * 1000;
return actus
  .filter(r => String(r['Statut']).trim() === 'Nouveau')
  .filter(r => {
    const t = new Date(r['Date publication']).getTime();
    return !isNaN(t) && t < limite;
  })
  .map(r => ({ json: { 'Clé (URL normalisée)': r['Clé (URL normalisée)'], 'Statut': 'Ignoré' } }));

// Workflow B (Delaunay Productions) — Nœud « Éclater les sources »
// Une sortie par (événement, source) pour aller lire chaque article,
// avec le sélecteur CSS propre au site s'il est renseigné dans l'onglet Sources (colonne R).
const SELECTEUR_DEFAUT = [
  'article p',
  '[itemprop="articleBody"] p',
  '.article-body p', '.article__body p', '.article-content p', '.article__content p',
  '.entry-content p', '.post-content p', '.content-article p',
  'main p',
].join(', ');

const hote = u => ((String(u || '').match(/^https?:\/\/([^\/?#]+)/i) || [])[1] || '').replace(/^www\./i, '').toLowerCase();
const selecteurs = $('Lire Sources').all().map(i => i.json)
  .filter(s => s['Domaine (filtre site:)'] && String(s['Sélecteur article (CSS) – optionnel'] || '').trim())
  .map(s => ({ domaine: String(s['Domaine (filtre site:)']).replace(/^www\./, '').toLowerCase(), css: String(s['Sélecteur article (CSS) – optionnel']).trim() }));

const sortie = [];
for (const it of $input.all()) {
  const e = it.json;
  if (e.aRediger === false) continue; // déjà couvert par un article : pas de lecture, pas d'appel IA
  for (const s of e.sources || []) {
    const h = hote(s.url);
    const perso = selecteurs.find(x => h === x.domaine || h.endsWith('.' + x.domaine));
    sortie.push({
      json: {
        idEvenement: e.idEvenement,
        url: s.url,
        media: s.media,
        titre: s.titre,
        extrait: s.extrait,
        selecteur: perso ? perso.css : SELECTEUR_DEFAUT,
        selecteurPerso: !!perso,
      },
    });
  }
}
return sortie;

// Workflow B (Delaunay Productions) — Nœud « Extraire le texte & regrouper »
// Entrées : sortie du nœud HTML « Extraire paragraphes » (+ HTML brut du nœud « Lire chaque article »).
// Pour chaque article, on prend dans l'ordre :
//   1. le texte structuré JSON-LD (articleBody), seulement si l'article est en accès libre ;
//   2. les paragraphes trouvés par le sélecteur CSS du site ;
//   3. un repli par regex sur les balises <p> ;
//   4. à défaut, le titre + le chapô du flux (texteComplet = false).
// On ne contourne jamais un paywall : un article marqué « réservé aux abonnés »
// est limité à ce que la page affiche publiquement.
// Bloc commun recopié en tête des nœuds Code du workflow B (Delaunay Productions)
const params = Object.fromEntries(
  $('Lire Paramètres').all().map(i => [String(i.json['Paramètre'] || '').trim(), i.json['Valeur']])
);
const nombre = (cle, defaut) => { const v = parseFloat(String(params[cle] ?? '').replace(',', '.')); return isNaN(v) ? defaut : v; };
const NB_MIN_SOURCES = nombre('Nb minimum de sources différentes', 2);
const NB_MAX_SOURCES = nombre('Nb maximum de sources par article', 4);
const NB_MAX_ARTICLES = nombre("Nb max d'articles par passage", 3);
const ATTENTE_H = nombre('Attente si une seule source', 48);
const CONSERVATION_J = nombre('Conservation dans le Sheet', 14);
const PROMPT = String(params['Prompt de rédaction (IA)'] || '').trim();
const FIAB_MIN = nombre('Fiabilité minimum (source unique)', 3);
const FIAB_GRAND_MEDIA = nombre('Fiabilité « grand média » (source unique, tous thèmes)', 4);
const PLAFOND_MEDIAS = nombre('Plafond médias dans le score', 3);
const BONUS_DIVERSITE = nombre('Bonus diversité', 4);
const BONUS_NORMANDIE = nombre('Bonus Normandie', 3);
const fiab = l => { const f = Number(l['Fiabilité source']); return isNaN(f) || l['Fiabilité source'] === '' ? 3 : f; };
const reconnue = l => fiab(l) >= FIAB_MIN;            // les sites inconnus (fiabilité 2) ne comptent pas
const prioriteDe = l => Number(l['Priorité thème']) || 1;
// Source unique acceptée : thème de priorité 1-2, OU grand média (fiabilité ≥ seuil), quel que soit le thème
const sourceUniqueOK = (prio, fiabilite) => prio < 3 || (Number(fiabilite) || 0) >= FIAB_GRAND_MEDIA;

const sansAccentB = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
// « Ouest-France », « Ouest France » et « ouest-france.fr » = le même média
const cleMedia = m => sansAccentB(m).replace(/\.(fr|com|net|org)$/, '').replace(/^www\./, '').replace(/[^a-z0-9]/g, '');
const cleTitre = t => sansAccentB(t).replace(/[^a-z0-9]+/g, ' ').trim();
const cleUrlB = u => {
  const m = String(u || '').trim().match(/^https?:\/\/([^\/?#]+)([^?#]*)/i);
  return m ? m[1].replace(/^www\./i, '').toLowerCase() + m[2].replace(/\/+$/, '') : String(u || '').trim();
};
// Deux lignes sont le même article si elles ont la même clé d'URL, ou le même média + le même titre
const signatures = r => [String(r['Clé (URL normalisée)'] || ''), cleMedia(r['Média source']) + '|' + cleTitre(r['Titre'])];
const RANG_STATUT = { 'Utilisé': 4, 'Doublon': 3, 'Ignoré': 2, 'Nouveau': 1 };

// Actus lues dans le Sheet, sans doublons (la suppression physique est faite par « Nettoyage : Actus brutes »)
const actus = (() => {
  const brutes = $('Lire Actus').all().map(i => i.json).filter(r => r && r['Clé (URL normalisée)']);
  const vues = new Map();
  const gardees = [];
  for (const r of [...brutes].sort((a, b) => (RANG_STATUT[b['Statut']] || 0) - (RANG_STATUT[a['Statut']] || 0))) {
    if (signatures(r).some(s => vues.has(s))) continue;
    signatures(r).forEach(s => vues.set(s, true));
    gardees.push(r);
  }
  return gardees;
})();
// Une actu « Nouveau » plus vieille que le délai d'attente n'est plus proposée (elle passe en « Ignoré »)
const fraiche = r => { const t = new Date(r['Date publication']).getTime(); return isNaN(t) || Date.now() - t < ATTENTE_H * 3600 * 1000; };

const MIN_COMPLET = 600; // nb de caractères minimum pour considérer qu'on a le vrai texte

const decoder = s => String(s || '')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"')
  .replace(/&#39;|&rsquo;|&#8217;|&apos;/g, "'").replace(/&laquo;/g, '«').replace(/&raquo;/g, '»')
  .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)));
const propre = s => decoder(String(s || '').replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();
const BRUIT = /cookie|abonnez|abonnement|newsletter|javascript|publicit|consentement|partager cet article|lire aussi|à lire également|inscrivez-vous|tous droits réservés|©/i;
const garder = p => p.length > 60 && !BRUIT.test(p);
const sansDoublons = arr => [...new Set(arr)];

function jsonLd(html) {
  const blocs = [...String(html || '').matchAll(/<script[^>]+application\/ld\+json[^>]*>([\s\S]*?)<\/script>/gi)];
  for (const b of blocs) {
    let d;
    try { d = JSON.parse(b[1].trim()); } catch (e) { continue; }
    const liste = [].concat(d, (d && d['@graph']) || []).flat();
    for (const o of liste) {
      if (!o || typeof o !== 'object') continue;
      const type = [].concat(o['@type'] || []).join(' ');
      if (!/Article|Posting/i.test(type)) continue;
      const libre = !(o.isAccessibleForFree === false || o.isAccessibleForFree === 'False' || o.isAccessibleForFree === 'false');
      return { corps: libre ? propre(o.articleBody || '') : '', libre, description: propre(o.description || '') };
    }
  }
  return null;
}

function regexParagraphes(html) {
  html = String(html || '').replace(/<(script|style|nav|footer|header|aside|form|figure)[\s\S]*?<\/\1>/gi, ' ');
  const zone = (html.match(/<article[\s\S]*?<\/article>/i) || [html])[0];
  return [...zone.matchAll(/<p[^>]*>([\s\S]*?)<\/p>/gi)].map(m => propre(m[1])).filter(garder);
}

const pageBloquee = html => /consent\.google|cookie-consent|didomi-host|captcha|cf-chl|Access Denied|Just a moment/i.test(String(html || '').slice(0, 5000))
  && regexParagraphes(html).length < 2;

const evenements = Object.fromEntries($('Scorer & sélectionner').all()
  .filter(i => i.json.aRediger !== false)
  .map(i => [i.json.idEvenement, { ...i.json, sources: [] }]));
const bruts = (() => { for (const nom of ['Lire chaque article', 'Lire chaque article1']) { try { return $(nom).all(); } catch (e) { /* nom suivant */ } } return []; })();
const eclat = $('Éclater les sources').all();

const items = $input.all();
for (let i = 0; i < items.length; i++) {
  let s;
  try { s = $('Éclater les sources').itemMatching(i).json; } catch (e) { s = (eclat[i] || {}).json; }
  if (!s || !s.idEvenement) continue;
  const brut = (bruts[i] && bruts[i].json && typeof bruts[i].json.data === 'string') ? bruts[i].json.data : '';

  let texte = '', methode = '';
  const ld = brut ? jsonLd(brut) : null;
  if (ld && ld.corps.length >= MIN_COMPLET) { texte = ld.corps; methode = 'json-ld'; }

  if (!texte) {
    const paras = [].concat(items[i].json && items[i].json.paragraphes || []).map(propre).filter(garder);
    const t = sansDoublons(paras).join('\n');
    if (t.length >= MIN_COMPLET) { texte = t; methode = s.selecteurPerso ? 'sélecteur du site' : 'sélecteur générique'; }
  }
  if (!texte && brut) {
    const t = sansDoublons(regexParagraphes(brut)).join('\n');
    if (t.length >= MIN_COMPLET) { texte = t; methode = 'regex'; }
  }

  let complet = !!texte;
  if (!complet) {
    const morceaux = [s.titre, ld && ld.description, s.extrait].filter(Boolean).map(propre);
    texte = sansDoublons(morceaux).join('\n');
    methode = !brut ? 'page non récupérée' : pageBloquee(brut) ? 'page bloquée (consentement / anti-bot)' : (ld && !ld.libre) ? 'article abonné' : 'texte introuvable';
  }

  const ev = evenements[s.idEvenement];
  if (ev) ev.sources.push({ media: s.media, url: s.url, titre: s.titre, texte: texte.slice(0, 5000), texteComplet: complet, methode });
}

// Longueur adaptée à la matière disponible (un article de blog est plus long qu'une brève de presse)
const consigneLongueur = ev => {
  const complets = ev.sources.filter(s => s.texteComplet);
  const total = complets.reduce((n, s) => n + s.texte.length, 0);
  if (ev.sources.length === 1) {
    const attribution = ` UNE SEULE SOURCE (${ev.sources[0].media}) : n'écris pas « selon ${ev.sources[0].media} » (les sources sont listées à la fin) et ne présente rien comme confirmé par d'autres médias.`;
    return complets.length
      ? { format: 'article (source unique)', consigne: 'Écris un article de 300 à 450 mots, en 3 ou 4 paragraphes : ce qui est nouveau, les détails, ce que cela change concrètement.' + attribution }
      : { format: 'brève (source unique)', consigne: 'Écris une BRÈVE de 130 à 180 mots, en 2 paragraphes. Tu ne disposes que du titre et du chapô : soigne la formulation, mais n\'ajoute aucun fait.' + attribution };
  }
  if (!complets.length) return { format: 'brève', consigne: 'Écris une BRÈVE de 150 à 220 mots, en 2 paragraphes. Tu ne disposes que de titres et de chapôs : soigne la formulation, mais n\'ajoute aucun fait.' };
  if (complets.length === 1 && total < 2500) return { format: 'article court', consigne: 'Écris un article de 350 à 500 mots, en 4 paragraphes : ce qui est nouveau, les détails, les réactions ou chiffres, ce que cela change concrètement.' };
  return { format: 'article', consigne: 'Écris un article de 500 à 750 mots, en 5 à 7 paragraphes : ce qui est nouveau, le contexte donné par les sources, les détails, les citations, ce que cela change concrètement, la suite.' };
};

// Paragraphe final sur Delaunay Productions (réglage de l'onglet Paramètres)
const PRESENTATION = String(params['Présentation Delaunay Productions'] || '').trim();
const AVEC_MARQUE = String(params["Paragraphe Delaunay Productions en fin d'article"] || 'Non').trim() === 'Oui' && PRESENTATION;
const consigneMarque = AVEC_MARQUE
  ? `Termine par un court paragraphe (2 phrases maximum) qui relie le sujet aux métiers de Delaunay Productions, en t'appuyant uniquement sur cette présentation : « ${PRESENTATION} ». Aucun chiffre, aucune référence client, aucune promesse, aucun superlatif.`
  : "Ne parle pas de Delaunay Productions dans l'article.";

return Object.values(evenements)
  .filter(e => e.sources.length)
  .map(e => {
    const l = consigneLongueur(e);
    return { json: { ...e, format: l.format, consigneLongueur: l.consigne, consigneMarque, nbTextesComplets: e.sources.filter(s => s.texteComplet).length, prompt: PROMPT } };
  });

// Workflow B (Delaunay Productions) — Nœud « Marquer les actus utilisées »
// Passe en « Utilisé » toutes les actus des événements qui ont donné un article.
const articles = $('Préparer l\'article').all().map(i => i.json).filter(a => a._garder !== false); // les trop courts sont traités à part
const evenements = Object.fromEntries($('Scorer & sélectionner').all().map(i => [i.json.idEvenement, i.json]));

const sortie = [];
for (const art of articles) {
  const ev = evenements[art['ID événement']];
  if (!ev) continue;
  for (const cle of ev.cles) {
    sortie.push({
      json: {
        'Clé (URL normalisée)': cle,
        'ID événement': ev.idEvenement,
        'Statut': 'Utilisé',
        'Article lié (ID)': art['ID article'],
        'Score événement': ev.score,
      },
    });
  }
}
return sortie;

// Workflow B (Delaunay Productions) — Nœud « Garder les articles assez longs »
// Seuls les articles dont le corps atteint le minimum de mots (onglet Paramètres, 50 par défaut) sont écrits dans « Articles ».
return $input.all().filter(i => i.json._garder !== false);

// Workflow B (Delaunay Productions) — Nœud « Actus des articles trop courts »
// Les actus d'un article trop court passent en « Ignoré » : sinon elles resteraient « Nouveau »
// et l'IA réécrirait le même article trop court à chaque passage.
const evenements = Object.fromEntries($('Scorer & sélectionner').all().map(i => [i.json.idEvenement, i.json]));
const sortie = [];
for (const it of $input.all()) {
  const art = it.json;
  if (art._garder !== false) continue;
  const ev = evenements[art['ID événement']];
  if (!ev) continue;
  for (const cle of ev.cles || []) {
    sortie.push({ json: { 'Clé (URL normalisée)': cle, 'Statut': 'Ignoré', 'Article lié (ID)': `Trop court (${art._nbMots} mots)` } });
  }
}
return sortie;
